// What jobs work on, by ID: files, with the first work each one's version
// covers, works, library folders and libraries. A season or episode comes
// with its series.
func (q *Queries) Subjects(ctx context.Context, ids string) ([]SubjectsRow, error) {
	rows, err := q.db.QueryContext(ctx, subjects, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SubjectsRow
	for rows.Next() {
		var i SubjectsRow
		if err := rows.Scan(
			&i.ID,
			&i.Path,
			&i.Kind,
			&i.Title,
			&i.Number,
			&i.ParentNumber,
			&i.Series,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateEmbeddedTrack = `-- name: UpdateEmbeddedTrack :exec
UPDATE media_track SET language = ?1, title = ?2, is_default = ?3, forced = ?4,
  hearing_impaired = ?5, info = ?6
WHERE id = ?7
`

type UpdateEmbeddedTrackParams struct {
	Language        sql.NullString
	Title           sql.NullString
	IsDefault       bool
	Forced          bool
	HearingImpaired bool
	Info            sql.NullString
	ID              id.ID
}

// A re-probe that finds the same type and codec at a stream index keeps
// the track's ID and refreshes the rest.
func (q *Queries) UpdateEmbeddedTrack(ctx context.Context, arg UpdateEmbeddedTrackParams) error {
	_, err := q.db.ExecContext(ctx, updateEmbeddedTrack,
		arg.Language,
		arg.Title,
		arg.IsDefault,
		arg.Forced,
		arg.HearingImpaired,
		arg.Info,
		arg.ID,
	)
	return err
}

const updateFileStat = `-- name: UpdateFileStat :one
UPDATE media_file SET size = ?1, mtime = ?2, status = 'present', gone_at = NULL,
  generation = generation + CAST(?3 AS BOOLEAN)
WHERE id = ?4
RETURNING generation
`

type UpdateFileStatParams struct {
	Size  int64
	Mtime int64
	Bump  bool
	ID    id.ID
}

// A file seen again: present, and a new generation when its content changed.
func (q *Queries) UpdateFileStat(ctx context.Context, arg UpdateFileStatParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, updateFileStat,
		arg.Size,
		arg.Mtime,
		arg.Bump,
		arg.ID,
	)
	var generation int64
	err := row.Scan(&generation)
	return generation, err
}
